function geo = bb_geometry()
%BB_GEOMETRY  Geometry of the ball-on-plate rig (auto-generated by blender/build_ball_balance.py).
%   Units: metres, kilograms. World frame: Z up, origin at centre of base top surface.
%   All body frames are translation-only from the world frame at the neutral pose.
%   STL files are expressed in their body frame. Masses are volume x density estimates.

geo.pivot        = [0 0 0.16];   % universal-joint centre
geo.ujoint.axis1 = [1 0 0];   % Base  -> Cross (lower yoke pins)
geo.ujoint.axis2 = [0 1 0];   % Cross -> Plate (upper yoke pins)
geo.horn.length  = 0.025;
geo.rod.length   = 0.09;
geo.servoX.shaft = [0.075 0 0.06];   geo.servoX.axis = [0 -1 0];  % +angle lifts the +X edge
geo.servoY.shaft = [0 0.075 0.06];   geo.servoY.axis = [1 0 0];   % +angle lifts the +Y edge
geo.servoX.hornDir0 = [1 0 0];   geo.servoY.hornDir0 = [0 1 0];   % horn direction at 0 rad
geo.rodX.bottom  = [0.1 0 0.06];   geo.rodX.top = [0.1 0 0.15];
geo.rodY.bottom  = [0 0.1 0.06];   geo.rodY.top = [0 0.1 0.15];
geo.plate.width        = 0.25;
geo.plate.surfaceWidth = 0.226;   % inside the rim
geo.plate.surfaceZ     = 0.186;   % rolling surface height (neutral)
geo.plate.rimHeight    = 0.006;   % rim above rolling surface
geo.ball.radius  = 0.02;
geo.ball.center0 = [0.035 -0.04 0.206];

here = fileparts(mfilename('fullpath'));
geo.body.Base = struct('frame', [0 0 0], 'mass', 3.99459, ...
    'color', [0.055 0.06 0.068], 'stl', fullfile(here, 'stl', 'Base.stl'));
geo.body.Cross = struct('frame', [0 0 0.16], 'mass', 0.0153281, ...
    'color', [0.7 0.7 0.72], 'stl', fullfile(here, 'stl', 'UJoint_Cross.stl'));
geo.body.Plate = struct('frame', [0 0 0.16], 'mass', 1.56024, ...
    'color', [0.8 0.81 0.83], 'stl', fullfile(here, 'stl', 'Plate.stl'));
geo.body.Ball = struct('frame', [0.035 -0.04 0.206], 'mass', 0.262587, ...
    'color', [0.92 0.92 0.93], 'stl', fullfile(here, 'stl', 'Ball.stl'));
geo.body.Horn_X = struct('frame', [0.075 0 0.06], 'mass', 0.00541523, ...
    'color', [0.03 0.16 0.62], 'stl', fullfile(here, 'stl', 'Horn_X.stl'));
geo.body.Rod_X = struct('frame', [0.1 0 0.06], 'mass', 0.0231172, ...
    'color', [0.92 0.92 0.93], 'stl', fullfile(here, 'stl', 'Rod_X.stl'));
geo.body.Horn_Y = struct('frame', [0 0.075 0.06], 'mass', 0.00541523, ...
    'color', [0.03 0.16 0.62], 'stl', fullfile(here, 'stl', 'Horn_Y.stl'));
geo.body.Rod_Y = struct('frame', [0 0.1 0.06], 'mass', 0.0231172, ...
    'color', [0.92 0.92 0.93], 'stl', fullfile(here, 'stl', 'Rod_Y.stl'));
end
